import{_ as l,c as i,o as e,ah as t}from"./chunks/framework.BkHe6ehV.js";const p=JSON.parse('{"title":"Meta 系列","description":"","frontmatter":{"title":"Meta 系列","date":"2026-09-23 12:00:00","create":"2026-09-23 12:00:00","categories":["mainllm"],"tags":["基模","Pretrain","SFT","RL"],"readingStats":{"words":6825,"minutes":20,"images":0}},"headers":[],"relativePath":"posts/llm/industry/mainllm/20-meta-series.md","filePath":"posts/llm/industry/mainllm/20-meta-series.md","lastUpdated":null}'),c={name:"posts/llm/industry/mainllm/20-meta-series.md"};function d(s,o,n,r,a,g){return e(),i("div",null,o[0]||(o[0]=[t('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block info"><div class="custom-block-title">2025</div><p><strong>2025.10 · <a href="#_2510-cwm-32b-code-world-model-执行轨迹-agent-rl">CWM</a></strong></p><ul><li>Python 执行轨迹与 Forager 交互数据用于世界模型 MidTrain，学习状态变化与动作后果。</li><li>三轮自举 SFT 后执行 SWE、编程、数学联合 RL，以执行反馈提高仓库任务能力。</li></ul></div><div class="custom-block note"><div class="custom-block-title">2024 及以前</div><p><strong>2024.07 · <a href="#_2407-llama-3-3-1-405b-数据质量-rs-sft-dpo">Llama 3 / 3.1</a></strong></p><ul><li>以 15T+ 语料扩展 Dense 模型，分阶段提升代码、数学、多语言与长上下文数据质量。</li><li>结合拒绝采样、SFT 与迭代 DPO，并把 405B 能力迁移到较小模型。</li></ul></div><h2 id="_2510-cwm-32b-code-world-model-执行轨迹-agent-rl" tabindex="-1">(2510) CWM (32B Code World Model，执行轨迹 + Agent RL) <a class="header-anchor" href="#_2510-cwm-32b-code-world-model-执行轨迹-agent-rl" aria-label="Permalink to &quot;(2510) CWM (32B Code World Model，执行轨迹 + Agent RL)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">CWM 论文摘要</div><p><strong>参考链接</strong></p><ul><li>📝 <a href="https://www.alphaxiv.org/abs/2510.02387" target="_blank" rel="noreferrer">paper</a>、<a href="https://github.com/facebookresearch/cwm" target="_blank" rel="noreferrer">code</a>、<a href="https://huggingface.co/facebook/cwm" target="_blank" rel="noreferrer">model</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>静态代码训练主要学习代码形式，缺少 <strong>执行状态变化</strong> 与 <strong>工具操作后果</strong> 的监督。</li><li>SWE Agent 需要理解仓库环境，并在多轮执行、测试与修改中完成任务。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>代码世界模型数据</strong>：Python 执行轨迹 + <strong>ForagerAgent</strong>，同时学习动作和环境反馈。</li><li><strong>长上下文 MidTrain</strong>：<code>8T</code> 通用预训练 → <code>5T</code> MidTrain，混合局部/全局注意力支持 <code>131K</code>。</li><li><strong>自举 SFT</strong>：三轮 SWE RL → 成功轨迹筛选 → SFT，建立稳定工具调用与推理能力。</li><li><strong>联合 RL</strong>：SWE、竞赛编程、Agentic Coding、数学混合训练，改进 GRPO 并异步采样。</li></ul><p><strong>模型效果(CWM-32B，SFT + Joint RL)</strong></p><ul><li>SWE-bench Verified 单次 <code>53.9%</code>，生成候选与测试后 <strong>best@16 达 <code>65.8%</code></strong>。</li><li>LiveCodeBench v5 <code>68.6%</code>；CruxEval-O 推理模式 <code>94.3%</code>，完整执行轨迹预测 <code>87.7%</code>。</li></ul><p><strong>重要结论</strong></p><ul><li><strong>执行轨迹</strong> 强化运行语义，<strong>Agent 交互轨迹</strong> 更直接改善仓库级任务，两类数据互补。</li><li>RL 后更频繁运行测试、定位相关文件；更换 Harness 和工具格式仍会明显影响效果。</li></ul><p><strong>核心贡献</strong></p><ul><li>将代码训练扩展到 <strong>状态—动作—下一状态</strong> 建模，贯穿 MidTrain、SFT 与可验证 RL。</li></ul><p><strong>未来方向</strong></p><ul><li>扩展其他语言与符号执行，将世界模型用于规划、稀疏奖励 RL 和更复杂的软件任务。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">静态代码与运行语义</div><p><strong>执行状态监督不足</strong></p><ul><li>源码描述程序，执行轨迹提供变量值、控制流与函数调用的实际变化。</li><li>世界模型学习给定状态与动作后的环境变化，为代码推理和行动规划提供基础。</li></ul><p><strong>仓库交互成本高</strong></p><ul><li>修复 Issue 涉及依赖安装、文件定位、编辑和测试，单个代码补全样本难以覆盖。</li><li>需要可执行仓库与长轨迹训练数据，使模型理解正确操作和失败操作的后果。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="可执行仓库与代码世界模型数据" tabindex="-1">可执行仓库与代码世界模型数据 <a class="header-anchor" href="#可执行仓库与代码世界模型数据" aria-label="Permalink to &quot;可执行仓库与代码世界模型数据&quot;">​</a></h4><div class="custom-block info"><div class="custom-block-title">Python 执行轨迹</div><p><strong>仓库环境</strong></p><ul><li><strong>Repo Agent</strong> 根据仓库文档安装依赖、配置测试；<strong>Activ</strong> 复用 GitHub Actions 构建环境。</li><li>Activ 在 CI 测试启动时捕获容器与依赖，保存为可重复执行的 Docker 镜像。</li><li>共构建超过 <code>35K</code> 个仓库镜像，支持程序追踪与 Agent 交互。</li></ul><p><strong>函数与仓库追踪</strong></p><ul><li>函数输入由 fuzzing 与 Llama 生成，累计追踪超过 <code>120M</code> 个函数。</li><li>仓库数据覆盖约 <code>21K</code> 个可追踪仓库镜像，通过测试执行捕获不同提交版本的调用轨迹。</li><li>每一步记录 <strong>局部变量状态、当前代码行、执行后的状态</strong>，保留调用和返回事件。</li><li>将长调用栈切成函数级片段，并补充相关源码上下文；不重复记录未变化的变量。</li></ul><p><strong>自然语言轨迹</strong></p><ul><li>使用 Qwen 将结构化执行过程转成自然语言，保留变量变化与最终输出。</li><li>过滤输出错误样本，连接程序运行语义与自然语言推理。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">ForagerAgent：仓库交互轨迹</div><p><strong>任务构建</strong></p><ul><li>收集约 <code>3M</code> 条轨迹，来自 <code>10.2K</code> 个镜像、<code>3.15K</code> 个仓库。</li><li><strong>Issue 修复 <code>55%</code></strong>：回到 Bug 修复前的提交，根据 Issue 与测试反馈生成修复轨迹。</li><li><strong>变异修复 <code>45%</code></strong>：修改 AST、删除语句或替换运算符，仅保留会使原测试失败的变异。</li><li>Llama、Qwen 作为 Agent，使用 bash、文件编辑与导航工具探索环境。</li></ul><p><strong>数据筛选与训练目标</strong></p><ul><li>排除 SWE-bench 仓库及其分叉；按动作序列去重，减少重复交互。</li><li><strong>同时保留成功与失败轨迹</strong>，使模型学习失败操作对应的环境变化。</li><li>对 <strong>Agent 动作与环境 observation 都计算预测损失</strong>。</li><li>observation 重复度高，随机屏蔽其中 <code>50%</code> 的损失，降低低信息反馈的训练占比。</li></ul></div><h4 id="混合注意力与长上下文-midtrain" tabindex="-1">混合注意力与长上下文 MidTrain <a class="header-anchor" href="#混合注意力与长上下文-midtrain" aria-label="Permalink to &quot;混合注意力与长上下文 MidTrain&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">模型结构与数据混合</div><p><strong>模型架构</strong></p><ul><li><code>32B</code> Dense，<code>64</code> 层，局部注意力与全局注意力按 <code>3:1</code> 交替。</li><li>局部窗口 <code>8K</code>，全局窗口 <code>131K</code>；文档之间使用 attention mask 隔离。</li><li>使用 Llama 3 tokenizer，并增加执行轨迹、推理格式的专用 token。</li></ul><p><strong>通用预训练 → 世界模型 MidTrain</strong></p><ul><li>通用预训练 <code>8T tokens</code>，上下文 <code>8K</code>，代码占 <code>30%</code>。</li><li>MidTrain <code>5T tokens</code>，上下文扩展到 <code>131K</code>，延续预训练优化器与学习率调度。</li><li>数据混合：<code>30%</code> CWM 相关数据 + <code>40%</code> 通用代码 + <code>30%</code> 通用预训练数据回放。</li><li>CWM 数据包含执行轨迹、ForagerAgent，以及 GitHub PR、编译器表示、Triton、Lean 等。</li></ul><p><strong>长序列训练</strong></p><ul><li>使用 Scaled RoPE，MidTrain 持续混合长文档，约 <code>30%</code> 文档超过 <code>65K</code>。</li><li>按长度分桶组织 batch，减少不同设备的计算时长差异。</li><li>通用数据回放用于保持知识、数学与普通代码能力。</li></ul></div><h4 id="成功轨迹自举与-sft" tabindex="-1">成功轨迹自举与 SFT <a class="header-anchor" href="#成功轨迹自举与-sft" aria-label="Permalink to &quot;成功轨迹自举与 SFT&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">SWE 轨迹自举</div><p><strong>三轮自举</strong></p><ul><li>从已有 SFT 模型开始 SWE RL，筛选 <strong>成功、格式正确、工具调用有效</strong> 的轨迹。</li><li>每轮用本轮筛选轨迹替换旧轨迹，从原始 MidTrain checkpoint 重做 SFT，再启动下一轮 SWE RL。</li><li>早期记录每题离线成功率，下一轮用作 GRPO 基线，可将每题 rollout 数降至 <code>1</code>。</li><li>最终 Joint RL 恢复在线组内基线。</li><li>重复三轮，用改进后的交互数据建立最终 SFT 模型，再进入联合 RL。</li></ul><p><strong>SFT 数据与目标</strong></p><ul><li>混合指令数据、SWE 成功轨迹与 OpenMathReasoning、OpenCodeReasoning 推理数据。</li><li>保留 <code>30%</code> MidTrain 数据回放，学习通用能力与执行状态预测。</li><li>训练 assistant 输出，支持普通回答和显式推理两种模式。</li><li>RL 阶段改用 <code>&lt;think&gt;</code> 标签，引入新的推理格式，增加初始探索空间。</li></ul></div><h4 id="多任务-agent-rl-与异步训练" tabindex="-1">多任务 Agent RL 与异步训练 <a class="header-anchor" href="#多任务-agent-rl-与异步训练" aria-label="Permalink to &quot;多任务 Agent RL 与异步训练&quot;">​</a></h4><div class="custom-block danger"><div class="custom-block-title">可验证任务与奖励</div><p><strong>SWE 任务</strong></p><ul><li>从仓库镜像、Issue/PR 以及 SWE-Gym、R2E-Gym 构造约 <code>12.6K</code> 个任务。</li><li>按 SFT 模型多次试解的成功率分层，过滤过易任务，初期为零成功率难题提供提示。</li><li>动作空间：<code>bash + edit + create + submit</code>；最多 <code>128</code> 轮，保留历史推理。</li><li>全部测试通过奖励 <code>+1</code>；失败时，patch 相似度高于阈值给 <code>0</code>，否则 <code>-1</code>。</li></ul><p><strong>竞赛编程与 Agentic Coding</strong></p><ul><li>约 <code>81K</code> 个编程问题，去重并排除评测污染；答案通过全部单测才获得正奖励。</li><li>普通编程直接生成答案；Agentic Coding 可写测试、编译执行、分析失败并修改代码。</li><li>Agentic Coding 使用 Python/C++；普通编程后续加入 Rust、Go、Java、JavaScript。</li></ul><p><strong>数学任务</strong></p><ul><li>约 <code>278K</code> 道可验证问题，去除 SFT 模型不推理也能全部答对的简单题。</li><li>验证最终答案等价性，并检查推理结束与答案格式；正确 <code>+1</code>，错误 <code>-1</code>。</li><li>部分数学任务允许 Python 工具调用，单条轨迹最多 <code>4</code> 次。</li></ul></div><div class="custom-block danger"><div class="custom-block-title">GRPO：长度偏置与多轮交互</div><p><strong>优势与损失</strong></p><ul><li>只对 <strong>Agent 生成 token</strong> 计算策略损失，屏蔽工具 observation。</li><li>优势使用 <code>return − 组内基线</code>，<strong>去掉标准差归一化</strong>，减少题目难度偏置。</li><li>基线按 Agent token 数对轨迹 return 加权，缓解长失败轨迹主导 token 梯度的问题。</li><li>损失除以固定 token 上限，避免按实际轨迹长度归一化产生长度偏置。</li></ul><p><strong>稳定训练</strong></p><ul><li>非对称 clipping：<code>εlow=0.2, εhigh=0.25</code>，比例截断区间为 <code>[0.8, 1.25]</code>；不加 KL 正则。</li><li>跳过零优势轨迹与过旧轨迹；按 token 上限组 batch，降低有效 batch 的波动。</li><li>结合罕见 token 与低生成概率检测乱码，防止偶然成功的异常轨迹被强化。</li></ul><p><strong>长度奖励调度</strong></p><ul><li>编程和数学初期容易迅速拉长回答，给正确但过长的回答施加线性奖励衰减。</li><li>软阈值从 <code>8K</code> 逐步提高到 <code>64K</code>，先学习有效推理，再释放更长推理预算。</li></ul></div><div class="custom-block info"><div class="custom-block-title">联合课程与异步系统</div><p><strong>任务混合</strong></p><ul><li>初期 SWE/编程/数学按 <code>40%/40%/20%</code> 采样；后续调整为 <code>30%/50%/20%</code>。</li><li>移除难题提示，按当前成功率重新采样，主要保留成功率 <code>0.1–0.7</code> 的有效学习任务。</li><li>部分 SWE 轨迹关闭编辑插件，训练模型仅通过 shell 命令完成编辑。</li><li>训练数据中 <code>1/3</code> 用于 SFT 数据回放，NLL 系数 <code>0.1</code>，减轻能力遗忘。</li></ul><p><strong>异步 rollout</strong></p><ul><li>worker 持续采样，trainer 持续更新；每 <code>4</code> 个更新步向 worker 广播权重。</li><li>权重可在轨迹中途更新，沿用已有 KV Cache，减少等待长轨迹造成的空闲。</li><li>保存每个 token 实际生成时的 log-prob，计算重要性权重。</li><li>仅当轨迹最后生成的 token 仍落后当前策略超过 <code>100</code> 步时丢弃。</li><li>权重经 CPU 内存异步分发，环境在独立容器中执行，模型训练与代码执行解耦。</li></ul></div><h3 id="实验设置-midtrain-sft-joint-rl" tabindex="-1">实验设置(MidTrain + SFT + Joint RL) <a class="header-anchor" href="#实验设置-midtrain-sft-joint-rl" aria-label="Permalink to &quot;实验设置(MidTrain + SFT + Joint RL)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">训练与评测设置</div><p><strong>基础模型与训练超参</strong></p><ul><li>从头训练 <code>32B</code>；预训练与 MidTrain 共 <code>13T tokens</code>，峰值学习率 <code>8e-4</code>。</li><li>SFT：约 <code>100B tokens</code>，<code>50K</code> 步，上下文 <code>32K</code>，batch 约 <code>2M tokens</code>，学习率 <code>1e-5</code>。</li><li>Joint RL：约 <code>172B tokens</code>，学习率 <code>2.5e-7</code>，每题 <code>8</code> 条 rollout。</li><li>RL batch 从 <code>8.4M</code> 增至 <code>16.8M tokens</code>；最大上下文 <code>131K</code>，梯度裁剪 <code>0.1</code>。</li><li>预训练使用 <code>2048 H100</code>；RL 使用约 <code>2560–4608 H100</code>，采样与训练分开部署。</li></ul><p><strong>数据消融</strong></p><ul><li><code>8B</code> 模型统一预训练 <code>6T</code>，再用 <code>1T</code> MidTrain 比较 PR、执行轨迹、Forager 数据组合。</li><li>各组均完成同类 SFT，<strong>不进行 RL</strong>，比较执行预测、轨迹 NLL 与 SWE 解题率。</li></ul><p><strong>评测协议</strong></p><ul><li>默认 <code>temperature=1.0, top-p=0.95</code>；SWE 单次结果取 <code>4</code> 轮评测平均。</li><li>SWE TTS：每题生成 <code>16</code> 个 patch 和 <code>40</code> 个新测试。</li><li>先过滤无法复现原 Bug 的测试，再保留 <code>Top-5</code> 多数测试。</li><li>先按已有测试筛候选，再按新测试选择；并列时优先多数 patch，再选更短轨迹。</li><li>执行预测：CruxEval；代码：LiveCodeBench、Aider Polyglot；长上下文：LoCoDiff、RULER。</li></ul></div><h3 id="关键结果-cwm-32b-sft-joint-rl" tabindex="-1">关键结果(CWM-32B，SFT + Joint RL) <a class="header-anchor" href="#关键结果-cwm-32b-sft-joint-rl" aria-label="Permalink to &quot;关键结果(CWM-32B，SFT + Joint RL)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">世界模型数据的作用</div><p><strong>执行理解与 Agent 交互分别获益</strong></p><ul><li><code>8B</code> 消融中，加入执行轨迹后 CruxEval-O 从 <code>44.6 → 73.9</code>，运行语义预测明显提升。</li><li>继续加入 Forager 数据，SWE 从 <code>18.4 → 22.1</code>，同时降低 Agent 轨迹 NLL。</li><li>PR 数据提供补丁监督，执行轨迹提供运行状态，交互轨迹补充仓库操作，三者组合效果最好。</li></ul><p><strong>世界模型与自然语言推理互补</strong></p><ul><li>最终 CWM 的 CruxEval-O：自然语言推理 <code>94.3%</code>，完整执行轨迹预测 <code>87.7%</code>。</li><li>完整轨迹平均约 <code>497 tokens</code>，自然语言推理约 <code>1164 tokens</code>，执行表示更紧凑。</li><li>模型能预测中间变量与执行动作，为后续规划、验证研究提供了可操作的状态表示。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">SWE 效果与交互行为</div><p><strong>候选选择决定 TTS 收益</strong></p><ul><li>SWE 单次 <code>53.9%</code>，测试辅助 best@16 达 <code>65.8%</code>；单纯 patch 多数投票为 <code>58.4%</code>。</li><li><code>40</code> 个候选的 pass@40 达 <code>80.4%</code>，但 best@k 在约 <code>16</code> 个候选后趋于饱和。</li><li>正确候选存在与正确选择候选是两项能力，测试质量仍限制 TTS 收益。</li></ul><p><strong>RL 学习实际工作习惯</strong></p><ul><li>前 <code>4000</code> 步中，主动运行测试的轨迹比例从 <code>57% → 74%</code>。</li><li>修改相关文件的召回率从 <code>58% → 66%</code>，文件定位随 RL 改善。</li><li>更换为 OpenHands，<code>128</code> 轮时得分 <code>42.6%</code>；原 Harness 的 bash-only 为 <code>42.1%</code>。</li><li>工具格式与训练分布匹配仍影响效果，增加交互轮数不保证持续提升。</li></ul><p><strong>代码与数学能力</strong></p><ul><li>LiveCodeBench v5/v6 为 <code>68.6%/63.5%</code>，具备同规模模型中较强的竞赛编程能力。</li><li>MATH-500 <code>96.6%</code>、AIME 2024 <code>76.0%</code>；数学能力仍弱于部分同规模专门推理模型。</li></ul></div><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">代码世界模型的扩展</div><ul><li><strong>数据覆盖</strong>：从显式 Python 执行扩展到其他编程语言、符号执行与更复杂环境。</li><li><strong>规划与验证</strong>：利用预测的执行状态筛选行动、验证推理，减少真实环境交互成本。</li><li><strong>世界模型与 RL</strong>：让模型先理解环境动力学，再通过稀疏可验证奖励学习行动策略。</li><li><strong>跨任务泛化</strong>：研究怎样通过提示与微调，稳定地将执行建模收益迁移到更多任务。</li></ul></div><h2 id="_2407-llama-3-3-1-405b-数据质量-rs-sft-dpo" tabindex="-1">(2407) Llama 3 / 3.1 (405B，数据质量 + RS/SFT/DPO) <a class="header-anchor" href="#_2407-llama-3-3-1-405b-数据质量-rs-sft-dpo" aria-label="Permalink to &quot;(2407) Llama 3 / 3.1 (405B，数据质量 + RS/SFT/DPO)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">Llama 3 论文摘要</div><p><strong>参考链接</strong></p><ul><li>📝 <a href="https://www.alphaxiv.org/abs/2407.21783" target="_blank" rel="noreferrer">paper</a>。</li><li>报告 <strong>The Llama 3 Herd of Models</strong> 的主要实验对应 <code>2024.07</code> 发布的 <strong>Llama 3.1</strong>。</li></ul><p><strong>问题背景</strong></p><ul><li>提升开放权重模型的通用能力，同时支持代码、推理、多语言、长上下文与工具调用。</li><li>模型扩大后，数据质量、训练稳定性与能力间的数据配比成为关键问题。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>预训练</strong>：网页精细清洗、领域筛选与数据配比，<code>15.6T tokens</code>，上下文 <code>8K → 128K</code>。</li><li><strong>迭代后训练</strong>：RM 选优 → RS/SFT → DPO，共 <code>6</code> 轮，加入格式 mask 与 chosen NLL。</li><li><strong>能力数据构建</strong>：代码执行反馈、推理验证、长文档合成、逐消息工具反馈，补足难样本。</li><li><strong>多模态扩展实验</strong>：冻结语言模型，分别接入视觉与语音编码器、adapter。</li></ul><p><strong>模型效果(Llama 3.1-405B-Instruct，SFT + DPO)</strong></p><ul><li>HumanEval <code>89.0</code>、MATH <code>73.8</code>、IFEval <code>88.6</code>、BFCL <code>88.5</code>。</li><li>通用能力接近同期闭源模型；代码、复杂推理与部分多语言任务仍有差距。</li></ul><p><strong>重要结论</strong></p><ul><li><strong>高质量数据、规模与简单训练流程</strong> 是主要收益来源，Dense 架构即可取得较强效果。</li><li><code>405B</code> 直接学习自身未验证的代码输出收益有限，<strong>执行反馈与纠错</strong> 是合成数据的关键。</li><li>少量长上下文 SFT 数据可保留长文档能力；只做短文本 SFT 会造成退化。</li></ul><p><strong>核心贡献</strong></p><ul><li>公开 <code>8B/70B/405B</code> 基础与指令模型，给出数据处理、后训练和大规模训练的完整工程路线。</li></ul><p><strong>未来方向</strong></p><ul><li>继续提高数据质量与训练规模，扩展多模态能力，并改善推理泛化、事实可靠性和评测。</li></ul></div><h3 id="问题背景-1" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-1" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">从通用语言模型到可用助手</div><p><strong>系列变化</strong></p><ul><li><strong>Llama 3，2024.04</strong>：<code>8B/70B</code>，主要面向英语，上下文 <code>8K</code>。</li><li><strong>Llama 3.1，2024.07</strong>：新增 <code>405B</code>，统一扩展到 <code>128K</code>，增强多语言与工具调用。</li></ul><p><strong>训练难点</strong></p><ul><li>通用、代码、数学与多语言数据存在质量和比例差异，单纯增加 token 不足以平衡能力。</li><li>合成回答可能重复模型错误，需要外部执行反馈、偏好评价与难度筛选。</li><li>长上下文预训练能力容易在短文本后训练中丢失，需要配套的数据与训练流程。</li></ul></div><h3 id="核心方法-1" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-1" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="高质量预训练与上下文扩展" tabindex="-1">高质量预训练与上下文扩展 <a class="header-anchor" href="#高质量预训练与上下文扩展" aria-label="Permalink to &quot;高质量预训练与上下文扩展&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">网页清洗与领域数据</div><p><strong>网页处理</strong></p><ul><li>自建 HTML parser，去除导航等模板内容，保留代码结构、数学公式和图片 alt 属性中的公式文本。</li><li><strong>URL 去重</strong> 保留最新页面；<strong>MinHash 文档去重</strong> 去除近似重复；<strong>行级去重</strong> 清理高频模板。</li><li>根据重复 n-gram、异常 token 分布等规则，过滤日志、乱码与低质量文档。</li><li>用 Llama 标注质量，再训练 DistilRoBERTa 分类器，批量筛选高质量网页。</li></ul><p><strong>领域筛选与数据配比</strong></p><ul><li>代码、数学独立构建分类器与提取规则，保留推导过程、STEM 推理及代码解释。</li><li>多语言数据先识别语言，再执行语言内去重、质量过滤与排序。</li><li>最终配比约为通用知识 <code>50%</code>、数学/推理 <code>25%</code>、代码 <code>17%</code>、多语言 <code>8%</code>。</li><li>用知识类别分类器降低过量网页类别的占比，再通过小规模实验比较混合方案。</li></ul><p><strong>高质量数据验证</strong></p><ul><li>对训练中期的 <code>8B</code> 模型做短程退火，混入候选数据，低成本判断小数据源是否有效。</li><li>用 <strong>训练计算量 → 下游任务 NLL → 任务准确率</strong> 的两阶段拟合，预测大模型效果。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">Dense 架构与长上下文</div><p><strong>架构调整</strong></p><ul><li>保持 Dense Transformer，使用 <strong>GQA</strong>，<code>8</code> 个 KV heads，降低解码缓存开销。</li><li>词表扩至 <code>128K</code>，增加非英语 token，提高文本压缩率与多语言表示效率。</li><li>RoPE 基频 <code>500K</code>；同一 packed sequence 的不同文档之间屏蔽 attention。</li></ul><p><strong>预训练流程</strong></p><ul><li>以 <code>8K</code> 上下文完成主体预训练，随后用约 <code>800B tokens</code> 逐步适配长序列。</li><li>分 <code>6</code> 个阶段扩展至 <code>128K</code>；每阶段检查短文本效果恢复与长文档检索能力。</li><li>最后使用高质量数据退火，学习率降至 <code>0</code>，并对末期 checkpoint 做参数平均。</li><li><code>405B</code> 按计算预算选取规模；<code>8B/70B</code> 训练更充分，以降低部署时的计算需求。</li></ul></div><div class="custom-block info"><div class="custom-block-title">大规模训练与推理</div><p><strong>4D 并行</strong></p><ul><li>组合 <strong>TP、PP、CP、FSDP</strong>，分别切分张量、模型层、上下文和数据/优化器状态。</li><li>长上下文按前后成对的片段分配设备，平衡因果注意力不同位置的计算量。</li><li>调整 pipeline micro-batch 调度与首尾层分配，减少流水线空闲和设备负载差异。</li></ul><p><strong>FP8 推理</strong></p><ul><li>主要量化 FFN，保留 attention、首尾 Transformer 层的精度。</li><li>按行计算量化尺度，并限制异常激活造成的尺度扩大，减少生成异常。</li><li>同时检查大批回答的 RM 分布，补充传统 benchmark 难以反映的质量变化。</li></ul></div><h4 id="rm、拒绝采样与迭代-dpo" tabindex="-1">RM、拒绝采样与迭代 DPO <a class="header-anchor" href="#rm、拒绝采样与迭代-dpo" aria-label="Permalink to &quot;RM、拒绝采样与迭代 DPO&quot;">​</a></h4><div class="custom-block danger"><div class="custom-block-title">六轮后训练</div><p><strong>人类偏好与 RM</strong></p><ul><li>同一 prompt 从不同模型采样两个回答，人工比较，并进一步编辑较好的回答。</li><li>构造 <strong>edited &gt; chosen &gt; rejected</strong> 的排序，用历轮偏好数据训练 RM。</li><li>过滤差异过小的回答对，保留有明确偏好的样本。</li></ul><p><strong>拒绝采样与 SFT</strong></p><ul><li>每个 prompt 从上一轮强模型生成约 <code>10–30</code> 个回答，使用 RM 选择最优候选。</li><li>混合拒绝采样结果、专项合成数据和少量人工数据，训练目标回答的交叉熵。</li><li><code>405B</code> 的输出还用于改善 <code>8B/70B</code> 的后训练数据质量。</li></ul><p><strong>迭代更新</strong></p><ul><li>每轮重新收集偏好、更新合成数据，再执行 SFT 与 DPO，共 <code>6</code> 轮。</li><li>RM 使用已有全部有效偏好数据；DPO 主要使用最新一批，贴近当前模型分布。</li><li>在 RM、SFT、DPO 各阶段，对不同数据或超参实验的模型做参数平均。</li></ul></div><div class="custom-block danger"><div class="custom-block-title">DPO 稳定性与数据筛选</div><p><strong>DPO 修改</strong></p><ul><li>对 chosen/rejected 的 <strong>消息头、终止符等格式 token 屏蔽 DPO loss</strong>。</li><li>减少对共同格式 token 的冲突优化，缓解结尾重复和过早终止。</li><li>对 chosen 回答加入 NLL，系数 <code>0.2</code>，防止其生成概率下降并保持格式稳定。</li></ul><p><strong>质量、难度与多样性</strong></p><ul><li>对样本标注主题、质量与难度，分别控制能力分布和复杂度。</li><li>RM 高分或 Llama 评审高分的样本进入候选，结合两类信号保留更多有效数据。</li><li>对话聚类后按 <strong>质量 × 难度</strong> 排序，再做语义去重。</li><li>难题若因回答错误被过滤，优先修订回答，避免训练集逐渐只剩简单问题。</li></ul><p><strong>事实性与安全数据</strong></p><ul><li>从预训练文档生成事实问题；反复回答仍错误的样本，构造不确定或拒答示范。</li><li>混合对抗请求与相近的正常请求，平衡安全拒答和错误拒答。</li></ul></div><h4 id="代码、推理与工具数据构建" tabindex="-1">代码、推理与工具数据构建 <a class="header-anchor" href="#代码、推理与工具数据构建" aria-label="Permalink to &quot;代码、推理与工具数据构建&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">代码专家与执行反馈</div><p><strong>领域专家</strong></p><ul><li>从主预训练分支继续训练代码专家，约 <code>1T tokens</code>，代码占比超过 <code>85%</code>。</li><li>通过仓库代码将专家上下文扩至 <code>16K</code>，再做代码 SFT/DPO，辅助标注与拒绝采样。</li></ul><p><strong>执行反馈合成</strong></p><ul><li>随机代码片段引导生成多样问题，再生成解法、注释与单元测试。</li><li>先经过 parser/linter，再在容器执行单测，检查语法、运行时与部分语义错误。</li><li>将错误代码与 <code>stdout/stderr/return code</code> 回传模型，迭代修正代码或测试。</li><li><strong>只保留通过检查的对话</strong>，同时收录失败到纠正的过程；约 <code>20%</code> 解法经过自纠正。</li></ul><p><strong>语言翻译与回译</strong></p><ul><li>将 Python/C++ 样本转成较少见语言，再经解析、编译与执行检查。</li><li>对注释、文档、解释任务，先生成说明，再由说明回译代码，与原代码比较一致性。</li><li>代码合成数据累计超过 <code>2.7M</code> 条，覆盖生成、解释、文档与调试。</li></ul></div><div class="custom-block note"><div class="custom-block-title">数学推理与长文档合成</div><p><strong>推理数据</strong></p><ul><li>按数学技能分类收集问题，并从预训练材料构造问答，补充薄弱技能。</li><li>生成多条逐步解答，通过最终答案验证、自检与过程奖励模型过滤错误步骤。</li><li>难题使用 <strong>MCTS + 步骤奖励模型</strong> 搜索有效推理链；代码执行提供额外验证信号。</li><li>保留错误解答及反馈纠正，训练模型利用反馈改善推理。</li></ul><p><strong>长上下文 SFT</strong></p><ul><li>长文档分成 <code>8K</code> 片段生成 QA，训练时提供完整文档，要求定位相关信息。</li><li>分块摘要后再汇总，构造需要全局理解的摘要与问答。</li><li>仓库中移除被多个文件依赖的模块，让模型根据依赖关系识别缺失模块并补全代码。</li><li>按 <code>16K/32K/64K/128K</code> 分桶，约 <code>0.1%</code> 长上下文样本即可兼顾短长任务。</li></ul><p><strong>多语言补充</strong></p><ul><li>多语言专家提供高质量标注，结合原生语言对话、NLP 数据改写和拒绝采样。</li><li>翻译经验证的数学推理数据，补足非英语定量推理能力。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">工具轨迹与逐消息反馈</div><p><strong>工具任务合成</strong></p><ul><li>支持搜索、Python 和 Wolfram Alpha；完整样本包含 <strong>请求 → 调用 → 输出 → 回答</strong>。</li><li>多步任务交替生成推理与工具调用，工具结果由真实执行获得。</li><li>加入启用工具但无需调用的简单问题，训练模型判断何时使用工具。</li></ul><p><strong>人类反馈</strong></p><ul><li>对工具调用前后每一条 assistant 消息做偏好比较或编辑，再继续对话。</li><li>人工评价调用是否合适、如何解释输出；不修改工具返回内容。</li><li>工具任务未使用拒绝采样，主要依靠合成冷启动与后续逐消息反馈。</li></ul><p><strong>新工具泛化</strong></p><ul><li>从 The Stack 提取真实函数定义与调用，生成对应自然语言请求。</li><li>覆盖单次、嵌套、并行调用，以及多轮 API 对话，训练时提供工具签名与说明。</li></ul></div><h4 id="组合式多模态扩展" tabindex="-1">组合式多模态扩展 <a class="header-anchor" href="#组合式多模态扩展" aria-label="Permalink to &quot;组合式多模态扩展&quot;">​</a></h4><div class="custom-block info"><div class="custom-block-title">视觉与语音研究模型</div><p><strong>视觉接入</strong></p><ul><li>ViT 编码图像，通过插入语言模型的 cross-attention 接入视觉特征。</li><li>冻结语言模型，训练视觉 encoder 与 adapter，保持原有文本能力。</li><li>用约 <code>6B</code> 图文对训练，再进行高分辨率退火与多模态 SFT/DPO。</li><li>视频增加时间聚合器与视频 cross-attention，压缩多帧表示，仅更新视频相关参数。</li></ul><p><strong>语音接入</strong></p><ul><li>Conformer 使用约 <code>15M</code> 小时音频做自监督训练，再由 adapter 转成语言模型输入表示。</li><li>联合训练 ASR、翻译与语音对话，更新语音 encoder/adapter，继续冻结语言模型。</li><li>语音生成利用 Llama 中间表示改善文本归一化与韵律，支持流式输出。</li><li>上述多模态部分为报告中的研究实验，区别于本次公开的 Llama 3.1 文本模型。</li></ul></div><h3 id="实验设置-预训练、sft-与-dpo" tabindex="-1">实验设置(预训练、SFT 与 DPO) <a class="header-anchor" href="#实验设置-预训练、sft-与-dpo" aria-label="Permalink to &quot;实验设置(预训练、SFT 与 DPO)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">训练配置与评测协议</div><p><strong>模型与预训练</strong></p><ul><li>模型规模 <code>8B/70B/405B</code>；主要报告 <code>405B</code> 的完整训练流程。</li><li><code>405B</code>：<code>126</code> 层、hidden size <code>16384</code>、<code>128</code> 个 attention heads，训练 <code>15.6T tokens</code>。</li><li>AdamW，峰值学习率 <code>8e-5</code>，warmup <code>8000</code> 步；batch 从 <code>4M → 8M → 16M tokens</code>。</li><li>训练最多使用 <code>16K H100</code>，长上下文阶段开启 CP；比较小模型与大模型的 scaling 预测。</li></ul><p><strong>后训练</strong></p><ul><li>SFT 学习率 <code>1e-5</code>，每轮约 <code>8.5K–9K</code> 步，prompt token 不计算损失。</li><li>DPO 学习率 <code>1e-5</code>、<code>β=0.1</code>，chosen NLL 系数 <code>0.2</code>。</li><li>各轮同时评估代码、推理、通用对话、长上下文与多语言，调整混合比例。</li></ul><p><strong>评测任务</strong></p><ul><li>代码：HumanEval、HumanEval+、MBPP/EvalPlus、MultiPL-E，报告 <code>pass@1</code>。</li><li>数学：GSM8K <code>8-shot CoT</code>、MATH <code>0-shot CoT</code>；通用：MMLU、MMLU-Pro、IFEval。</li><li>工具：BFCL、Nexus、API-Bank、API-Bench；长上下文：Multi-needle、InfiniteBench。</li><li>人评约 <code>7000</code> 个 prompt，覆盖单轮、多轮及多语言；按能力与难度分层采样。</li><li>后训练数据用 benchmark prompt 精确匹配去污染，并另做预训练数据污染分析。</li></ul></div><h3 id="关键结果-llama-3-1-8b-70b-405b-instruct" tabindex="-1">关键结果(Llama 3.1-8B/70B/405B-Instruct) <a class="header-anchor" href="#关键结果-llama-3-1-8b-70b-405b-instruct" aria-label="Permalink to &quot;关键结果(Llama 3.1-8B/70B/405B-Instruct)&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">模型规模与能力提升</div><p><strong>代码与推理</strong></p><ul><li>HumanEval：<code>8B/70B/405B</code> 分别为 <code>72.6/80.5/89.0</code>，模型扩大带来稳定收益。</li><li><code>405B</code> 的 HumanEval+ 为 <code>82.3</code>，更严格的测试仍会暴露原始单测未覆盖的错误。</li><li>MATH 为 <code>51.9/68.0/73.8</code>；大模型改善数学能力，复杂推理仍未全面达到同期最强模型。</li></ul><p><strong>指令、工具与多语言</strong></p><ul><li><code>405B</code> 的 IFEval 为 <code>88.6</code>，BFCL 为 <code>88.5</code>，多轮偏好对齐与工具数据有效。</li><li>MGSM 为 <code>91.6</code>，多语言专家和推理数据扩充改善非英语数学能力。</li><li>人评中多轮推理、代码强于 GPT-4，但部分多语言能力仍落后；各能力收益不完全一致。</li></ul><p><strong>长上下文</strong></p><ul><li><code>405B</code> Multi-needle 平均召回 <code>98.1</code>，InfiniteBench En.MC <code>83.4</code>。</li><li>检索、长文档理解均有较强表现；<code>128K</code> 适配需要预训练与 SFT 数据共同支持。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">数据与训练结论</div><p><strong>合成数据需要验证</strong></p><ul><li>小模型能从强教师直接获益；<code>405B</code> 使用自身未经验证的输出，可能没有收益甚至退化。</li><li>执行反馈提供额外正确性信号，迭代纠错使模型学习超出原始回答的数据。</li><li>严格过滤可能同时丢失难题，修订难题回答比单纯删除更有利于保持训练难度。</li></ul><p><strong>长上下文与对齐可以兼顾</strong></p><ul><li>只用短文本 SFT 会损伤长上下文能力；加入少量合成长文档样本即可明显缓解。</li><li>在长上下文 SFT 之后，短文本 DPO 未造成同样的退化，阶段间需要不同数据配置。</li></ul><p><strong>效率与多模态扩展</strong></p><ul><li><code>405B</code> 大规模训练 BF16 MFU 约 <code>38%–43%</code>；FP8 推理的 prefill 吞吐最高提升约 <code>50%</code>。</li><li>视觉研究模型 <code>405B-V</code> 的 MMMU 为 <code>64.5</code>、DocVQA 为 <code>92.6</code>，冻结语言骨干仍能扩展视觉能力。</li></ul></div><h3 id="未来方向-1" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-1" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">数据、泛化与多模态</div><ul><li><strong>质量与规模</strong>：扩大高质量、多样化数据，继续优化配比与可稳定扩展的训练流程。</li><li><strong>推理泛化</strong>：改善对抗数学、复杂代码与多语言任务，减少对题目形式和分布的依赖。</li><li><strong>多模态整合</strong>：完善视觉、视频和语音模块，推进组合式模型的进一步训练与评估。</li><li><strong>可靠性与评测</strong>：持续改善事实性与安全性，控制训练污染与 benchmark 过拟合。</li></ul></div>',53)]))}const h=l(c,[["render",d]]);export{p as __pageData,h as default};
